import{j as e}from"./vendor-motion-D-QS5Tde.js";import{H as s}from"./index-DTryBJkQ.js";import{N as i,F as n}from"./Footer-KawF-dDP.js";import{P as r,C as t,N as o}from"./NextProject-BUYY37sz.js";import{C as a}from"./CsSection-D4zIf1tb.js";import{C as l}from"./CsCredits-DAUbZekd.js";import{B as c}from"./BottomNav-BQIsGLMm.js";import"./vendor-react-P2F7fkol.js";import"./vendor-three-CMud_36L.js";function y(){return e.jsxs(e.Fragment,{children:[e.jsxs(s,{children:[e.jsx("title",{children:"TEDx VIT Pune · Parth Pawar"}),e.jsx("meta",{name:"description",content:"Art Director for TEDx VIT Pune — led a team of 65+ people to design, fabricate, and build a parallax cityscape stage for 800+ attendees. From brand identity to structural construction."}),e.jsx("meta",{property:"og:type",content:"article"}),e.jsx("meta",{property:"og:title",content:"TEDx VITPUNE · Parth Pawar"}),e.jsx("meta",{property:"og:description",content:"Art Director for TEDx VIT Pune — led 65+ people to build a parallax cityscape stage for 800+ attendees."}),e.jsx("meta",{property:"og:image",content:"https://parthpawar.com/Assets/images/tedx.png"})]}),e.jsx(i,{}),e.jsxs("main",{id:"main-content",className:"project-main",style:{"--project-color":"#E53E3E"},children:[e.jsx(r,{backLink:"/work",categorySlug:"brand-visual",backLabel:"Back to Work",tags:["Art Direction","Stage Design","Brand Identity","Fabrication"],title:"TEDx VIT Pune",subtitle:"Art directing a 65-person team to design, fabricate, and light a rotating parallax cityscape stage for 800+ attendees",info:[{label:"Role",value:"Art Director"},{label:"Team",value:"65+ volunteers"},{label:"Timeline",value:"Sept–Nov 2019"},{label:"Audience",value:"800+ attendees"},{label:"Year",value:"2019"}],heroImage:"/Assets/Projects/Tedxvitpune/Desktop/5.jpg",heroAlt:"Completed TEDxVITPune stage with parallax cityscape"}),e.jsx("div",{className:"wrap project-overview reveal",id:"cs-overview",children:e.jsxs("div",{className:"proj-overview-grid",children:[e.jsxs("div",{className:"proj-overview-body",children:[e.jsx("h2",{className:"section-label",children:"The Challenge"}),e.jsx("p",{className:"proj-desc",children:"TEDxVITPune is one of Pune’s longest-running TEDx events, bringing together speakers, performers, and an audience of 800+ for a single day of ideas worth spreading. For the 2019 edition, the organizing committee wanted something the event had never attempted: a stage that was not just a backdrop, but a spatial experience — one that transformed throughout the day and reinforced the event’s theme visually. The brief was open-ended and the budget was tight. Everything had to be designed, built, and installed by students within eight weeks."})]}),e.jsxs("div",{className:"proj-overview-body",children:[e.jsx("h2",{className:"section-label",children:"My Role"}),e.jsx("p",{className:"proj-desc",children:"Art Director — Aesthetic Head of TEDxVITPune. Responsible for brand identity, stage concept, structural design, fabrication oversight, lighting design, and team coordination across 65+ volunteers in design, fabrication, logistics, and on-site assembly."})]})]})}),e.jsx("section",{className:"cs-section reveal",id:"cs-brand",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"02 — Brand Identity"}),e.jsx("h2",{className:"cs-section-title",children:"Visual System"}),e.jsx(t,{style:{maxWidth:"720px"},children:e.jsx("p",{children:"The visual identity for TEDxVITPune 2019 needed to honor the established TEDx brand guidelines while carving out a distinct personality for this edition. I developed a cohesive system that extended from digital collateral to the physical stage itself."})}),e.jsxs("div",{style:{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(280px,1fr))",gap:"2rem",marginTop:"2.5rem"},children:[e.jsxs("div",{children:[e.jsx("p",{className:"cs-section-label",style:{marginBottom:"0.5rem"},children:"Color Palette"}),e.jsx(t,{children:e.jsx("p",{children:"Built around the signature TEDx red, the palette was extended with deep navy (#080B1E) and warm neutrals. The dark tones gave the brand a cinematic quality that translated directly to stage lighting—every digital design choice was made with the physical space in mind."})})]}),e.jsxs("div",{children:[e.jsx("p",{className:"cs-section-label",style:{marginBottom:"0.5rem"},children:"Typography"}),e.jsx(t,{children:e.jsx("p",{children:"Bold, geometric type for headlines paired with a clean sans-serif for body text. The typographic hierarchy was designed to work across print banners, projected slides, and stage signage—maintaining legibility at scales from phone screens to 12-foot backdrops."})})]}),e.jsxs("div",{children:[e.jsx("p",{className:"cs-section-label",style:{marginBottom:"0.5rem"},children:"Collateral"}),e.jsx(t,{children:e.jsx("p",{children:"The system unified social media graphics, event programs, speaker introduction cards, venue signage, attendee badges, and merchandise. Every touchpoint reinforced the same visual language, creating a cohesive brand experience from the moment attendees saw the event online to the moment they walked through the venue doors."})})]})]})]})}),e.jsx(a,{id:"cs-stage",label:"03 — Stage Design",title:"Parallax Cityscape",children:e.jsxs(t,{style:{maxWidth:"720px"},children:[e.jsx("p",{children:"The stage concept was a layered parallax cityscape—multiple planes of building silhouettes at varying depths that created an illusion of spatial depth when lit from behind. As speakers moved across the stage, the relationship between the layers shifted, making the backdrop feel alive rather than static."}),e.jsx("p",{children:"The design went through three major iterations. Initial sketches explored abstract geometric forms, but user testing with the organizing committee revealed that a recognizable urban skyline would resonate more strongly with the audience and provide better visual framing for speakers on camera."}),e.jsx("p",{children:"The final design featured five distinct depth layers, each cut from different materials to vary opacity and texture. The deepest layer was solid MDF painted matte black; mid-layers were semi-transparent fabric stretched over wooden frames; the foreground layer was detailed laser-cut acrylic. When backlit with programmable LEDs, the layers produced a subtle parallax effect visible from every seat in the auditorium."})]})}),e.jsx("section",{className:"cs-section reveal",children:e.jsxs("div",{className:"wrap",children:[e.jsx("h2",{className:"cs-display",style:{opacity:.25,fontSize:"clamp(3rem,8vw,7rem)",marginBottom:"2rem"},children:"Stage Design"}),e.jsx("figure",{className:"cs-img-full",style:{background:"transparent"},children:e.jsx("img",{src:"/Assets/Projects/Tedxvitpune/Desktop/1.jpg",alt:"TEDxVITPune stage design — speakers and performers on the parallax cityscape stage",loading:"lazy"})})]})}),e.jsx(a,{id:"cs-team",label:"04 — Team Leadership",title:"Coordinating 65+ People",children:e.jsxs(t,{style:{maxWidth:"720px"},children:[e.jsx("p",{children:"This was not a project I could build alone. As Art Director, I led a team of 65+ volunteers—most of whom had never worked on a production of this scale. The team was organized into three functional groups: Design (visual identity, signage, digital collateral), Fabrication (structural construction, material sourcing, painting), and Logistics (venue coordination, equipment rental, day-of setup)."}),e.jsx("p",{children:"I ran weekly all-hands meetings and daily standups with group leads during the final two weeks. The biggest leadership challenge was maintaining design quality across dozens of hands. I created detailed visual guides and templates for every fabrication task—specifying exact paint mixes, cut dimensions, and assembly sequences—so that volunteers with no design training could execute at the standard the event required."}),e.jsx("p",{children:"Delegation was essential, but so was knowing when to step in. I personally oversaw every critical juncture: the first structural test of the rotating mechanism, the lighting programming, and the final 48-hour install marathon before the event."})]})}),e.jsx(a,{id:"cs-process",label:"05 — Process",title:"Eight Weeks, Concept to Curtain",children:e.jsxs(t,{style:{maxWidth:"720px"},children:[e.jsxs("p",{children:[e.jsx("strong",{children:"Weeks 1–2: Concept & Brand."})," Developed the parallax cityscape concept and complete brand identity system. Presented three stage directions to the organizing committee; the parallax approach was selected unanimously. Simultaneously recruited and onboarded the full volunteer team."]}),e.jsxs("p",{children:[e.jsx("strong",{children:"Weeks 3–4: Structural Design."})," Translated the stage concept into engineering drawings. Worked with local fabricators to source materials and validate structural feasibility. Built a 1:10 scale model to test sightlines and lighting angles from every section of the auditorium."]}),e.jsxs("p",{children:[e.jsx("strong",{children:"Weeks 5–6: Fabrication."})," Full-scale construction began. Columns were built from wooden frames and MDF panels. The rotating stage platform was assembled and tested for smooth, silent rotation. Parallax layers were cut and painted. The team worked in shifts across two workshops."]}),e.jsxs("p",{children:[e.jsx("strong",{children:"Week 7: Lighting & Integration."})," Programmable LED strips were wired behind each parallax layer. Lighting scenes were programmed to match the event’s session structure—warm tones for talks, cooler tones for performances, dynamic color shifts for transitions. The rotating mechanism was integrated with the lighting controller for synchronized reveals."]}),e.jsxs("p",{children:[e.jsx("strong",{children:"Week 8: Install & Event Day."})," The entire stage was transported and assembled in the venue over 48 hours. Final lighting calibration, sound checks, and a full technical rehearsal. On event day, I directed all visual elements live—stage rotations, lighting cues, and backdrop changes—ensuring the 800+ attendees experienced a seamless production."]})]})}),e.jsx("section",{className:"cs-section reveal",children:e.jsxs("div",{className:"wrap",children:[e.jsx("h2",{className:"cs-display",style:{marginBottom:"2rem"},children:"Process"}),e.jsx("figure",{className:"cs-img-full",style:{background:"transparent"},children:e.jsx("img",{src:"/Assets/Projects/Tedxvitpune/Desktop/4.jpg",alt:"Behind-the-scenes process photos showing stage construction, column fabrication, lighting tests, and assembly",loading:"lazy"})})]})}),e.jsx(a,{id:"cs-reflections",label:"06 — Reflections",title:"What Leading This Taught Me",children:e.jsxs(t,{style:{maxWidth:"720px"},children:[e.jsx("p",{children:"TEDxVITPune was the first time I was responsible for both the creative vision and the operational execution of a large-scale production. Two lessons stayed with me."}),e.jsx("p",{children:"First, design systems are leadership tools. The visual guides and templates I created were not just about consistency—they were about giving 65 people the confidence to act without waiting for my approval. When the system is clear, people move faster and make better decisions on their own."}),e.jsx("p",{children:"Second, the gap between a concept and a built thing is where most projects fail. Ideas are cheap; execution at scale is what matters. Managing material constraints, volunteer fatigue, venue restrictions, and a hard deadline taught me more about design than any studio course. The stage worked because every aesthetic decision was also a structural decision, a budget decision, and a logistics decision. That integration—thinking across domains simultaneously—is what I now consider the core skill of design leadership."})]})}),e.jsx("section",{className:"cs-section cs-thanks reveal",children:e.jsxs("div",{className:"wrap",children:[e.jsx("h2",{className:"cs-thanks-title",children:"Thank You"}),e.jsx(l,{credits:[{role:"Art Director",name:"Parth Pawar"}]}),e.jsxs("div",{className:"cs-tags",style:{justifyContent:"center",marginTop:"2rem"},children:[e.jsx("span",{className:"cs-tag-item",children:"Art Direction"}),e.jsx("span",{className:"cs-tag-item",children:"Stage Design"}),e.jsx("span",{className:"cs-tag-item",children:"Parallax Concept"}),e.jsx("span",{className:"cs-tag-item",children:"Brand Identity"}),e.jsx("span",{className:"cs-tag-item",children:"Lighting Design"}),e.jsx("span",{className:"cs-tag-item",children:"Fabrication"}),e.jsx("span",{className:"cs-tag-item",children:"Team Leadership"}),e.jsx("span",{className:"cs-tag-item",children:"TEDx"})]})]})}),e.jsx(c,{sections:[{id:"cs-overview",label:"Overview"},{id:"cs-brand",label:"Brand Identity"},{id:"cs-stage",label:"Stage Design"},{id:"cs-team",label:"Team"},{id:"cs-process",label:"Process"},{id:"cs-reflections",label:"Reflections"}]})]}),e.jsx(o,{slug:"code-for-build",title:"Code for Build",image:"/Assets/images/code-for-build.jpg"}),e.jsx(n,{})]})}export{y as default};
